def evaluate_polynomial(eqn):
  x = int(input("Enter the value of x: "))
  result = 0
  for i in range(len(eqn)):
    elem = eqn[i]
    if elem[-1] == \'x\':
      coefficient = int(elem[:-1])
      if i == 0:
        result += coefficient * (x ** 2)
      elif i == 1:
        result += coefficient * x
      else:
        result += coefficient
    else:
      result += int(elem)

  return result

print(evaluate_polynomial("2x2 + 3x + 4"))
```

